style.css:
@-moz-document domain("youtube.com") {
/* Nền Kuromi */
    body, ytd-app {
        background: url("https://i.pinimg.com/originals/2a/9d/5a/2a9d5a1d57cb3c7f1aef7f9f8cfb67a8.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Overlay tối nhẹ để chữ dễ nhìn */
    ytd-app::before {
        content: "";
        position: fixed;
        top: 0; left: 0;
        width: 100%; height: 100%;
        background: rgba(0, 0, 0, 0.55);
        z-index: -1;
    }

    /* Thanh trên cùng */
    #masthead-container {
        background: rgba(44, 0, 62, 0.8) !important;
        border-bottom: 2px solid #ff8ccf !important;
    }

    /* Thanh tìm kiếm */
    #search-input #search {
        background: rgba(44, 0, 62, 0.7) !important;
        border: 2px solid #ff8ccf !important;
        border-radius: 25px !important;
        color: #fff !important;
    }

    /* Tiêu đề video */
    #video-title {
        color: #e5aaff !important;
        font-weight: bold !important;
    }
    #video-title:hover {
        color: #ff7dd1 !important;
    }

    /* Nút Subscribe */
    ytd-subscribe-button-renderer paper-button {
        background: #ff66b2 !important;
        color: #fff !important;
        border-radius: 20px !important;
        font-weight: bold !important;
    }
    ytd-subscribe-button-renderer paper-button:hover {
        background: #cc3399 !important;
    }

    /* Thumbnail bo tròn */
    ytd-thumbnail img {
        border-radius: 15px !important;
        border: 2px solid #ff8ccf !important;
    }

    /* Comment box */
    #placeholder-area {
        background: rgba(26, 0, 31, 0.7) !important;
        color: #ffccf9 !important;
        border-radius: 15px !important;
        padding: 5px !important;
    }
}
